AGENTS.md
// Feed navigation renders synthetic time buckets, not the folder tree.
import type { MouseEvent as ReactMouseEvent, RefObject } from "react";
import { useCallback } from "react";
import { useShallow } from "zustand/react/shallow";

import { useEditor } from "@/features/notes/editor/hooks/editor-context";
import { useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
import { type DesktopContextMenuState } from "@/app/hooks/use-tree-interactions";
import { useSelection } from "@/app/state/selection-store";
import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
import { focusNoScroll } from "@/shared/lib/dom";
import { computeRangeSelection } from "@/shared/lib/selection";
import { isCurrentWeekFeedNode } from "../model/feed-tree-model";
import { TreeNode } from "./tree-node";

type FeedPanelProps = {
  paneBodyRef: RefObject<HTMLDivElement | null>;
  onNavigateToNotes?: () => void;
  onPaneClick?: () => void;
  onPaneKeyDown?: (event: React.KeyboardEvent<HTMLDivElement>) => void;
  onOpenContextMenu: (state: DesktopContextMenuState) => void;
};

export function FeedPanel({
  paneBodyRef,
  onNavigateToNotes,
  onPaneClick,
  onPaneKeyDown,
  onOpenContextMenu,
}: FeedPanelProps) {
  const { clearDraft, clearNote } = useEditor();
  const {
    feedTreeData,
    feedNodeById,
    feedNoteFilter,
    activeFeedGroup,
    setActiveFeedGroup,
    expanded,
    setExpanded,
    allNotePreviews,
    shouldNestNotesInNavigation,
  } = useNotesTree();
  const currentWeekNodes = feedTreeData.filter(isCurrentWeekFeedNode);
  const earlierNodes = feedTreeData.filter((node) => !isCurrentWeekFeedNode(node));
  const {
    selectFolder,
    selectNote,
    setSelectedFolders,
    setLastSelectedFolder,
    setActiveFolder,
    selectedNotes,
    setSelectedNotes,
    lastSelectedNote,
    setLastSelectedNote,
    setActiveNote,
  } = useSelection(
    useShallow((state) => ({
      selectFolder: state.selectFolder,
      selectNote: state.selectNote,
      setSelectedFolders: state.setSelectedFolders,
      setLastSelectedFolder: state.setLastSelectedFolder,
      setActiveFolder: state.setActiveFolder,
      selectedNotes: state.selectedNotes,
      setSelectedNotes: state.setSelectedNotes,
      lastSelectedNote: state.lastSelectedNote,
      setLastSelectedNote: state.setLastSelectedNote,
      setActiveNote: state.setActiveNote,
    }))
  );

  const selectFeedGroup = useCallback(
    (groupId: string) => {
      onNavigateToNotes?.();
      setActiveFeedGroup(groupId);
      selectFolder(FEED_FOLDER_PATH);
      clearDraft();
      clearNote();
      focusNoScroll(paneBodyRef.current);
    },
    [
      clearDraft,
      clearNote,
      onNavigateToNotes,
      paneBodyRef,
      selectFolder,
      setActiveFeedGroup,
    ]
  );

  const handleNoteSelect = useCallback(
    (notePath: string, event: ReactMouseEvent, parentPath: string) => {
      onNavigateToNotes?.();
      const parentNode = feedNodeById.get(parentPath);
      const notePaths = parentNode?.notes.map((note) => note.path) || [];
      selectNote(
        notePath,
        FEED_FOLDER_PATH,
        computeRangeSelection(event, selectedNotes, notePaths, lastSelectedNote, notePath)
      );
      setActiveFeedGroup(parentPath);
      if (shouldNestNotesInNavigation) {
        focusNoScroll(paneBodyRef.current);
      }
    },
    [
      feedNodeById,
      lastSelectedNote,
      onNavigateToNotes,
      paneBodyRef,
      selectNote,
      selectedNotes,
      setActiveFeedGroup,
      shouldNestNotesInNavigation,
    ]
  );

  const handleToggle = useCallback(
    (event: ReactMouseEvent, id: string) => {
      event.stopPropagation();
      setExpanded((prev) => {
        const next = new Set(prev);
        if (next.has(id)) {
          next.delete(id);
        } else {
          next.add(id);
        }
        return next;
      });
    },
    [setExpanded]
  );

  const handleNoteContextMenu = useCallback(
    (event: ReactMouseEvent, notePath: string, parentPath: string) => {
      event.preventDefault();
      event.stopPropagation();
      const parentNode = feedNodeById.get(parentPath);
      const notePaths = parentNode?.notes.map((note) => note.path) || [];
      const targetPaths =
        selectedNotes.size > 1 && selectedNotes.has(notePath) ? Array.from(selectedNotes) : [notePath];
      setSelectedFolders(new Set([FEED_FOLDER_PATH]));
      setLastSelectedFolder(FEED_FOLDER_PATH);
      setActiveFolder(FEED_FOLDER_PATH);
      if (!selectedNotes.has(notePath)) {
        setSelectedNotes(new Set([notePath]));
        setLastSelectedNote(notePath);
      }
      setActiveFeedGroup(parentPath);
      setActiveNote(notePath);
      focusNoScroll(paneBodyRef.current);
      onOpenContextMenu({
        kind: "note",
        x: event.clientX,
        y: event.clientY,
        path: notePath,
        parentPath,
        targetPaths: targetPaths.length > 0 ? targetPaths : notePaths,
      });
    },
    [
      feedNodeById,
      onOpenContextMenu,
      paneBodyRef,
      selectedNotes,
      setActiveFeedGroup,
      setActiveFolder,
      setActiveNote,
      setLastSelectedFolder,
      setLastSelectedNote,
      setSelectedFolders,
      setSelectedNotes,
    ]
  );

  return (
    <div className="feed-panel-layout">
      <div
        className="nav-scroll-area focus:outline-none"
        ref={paneBodyRef}
        tabIndex={0}
        onKeyDown={onPaneKeyDown}
        onClick={(event) => {
          if (onPaneClick) {
            onPaneClick();
          }
          if (event.target === event.currentTarget && feedTreeData[0]) {
            selectFeedGroup(activeFeedGroup || feedTreeData[0].id);
          }
        }}
      >
        <div className="pane-body tree-root feed-navigation-tree">
          <div className="feed-section-label">This week</div>
          {currentWeekNodes.map((node) => (
            <TreeNode
              key={node.id}
              node={node}
              depth={0}
              selectedIds={activeFeedGroup ? new Set([activeFeedGroup]) : new Set()}
              selectedNoteIds={selectedNotes}
              showNotesAsChildren={shouldNestNotesInNavigation}
              edgeSnap={null}
              expanded={expanded}
              feedMode
              onSelect={(event, id) => {
                event.stopPropagation();
                selectFeedGroup(id);
              }}
              onToggle={handleToggle}
              onNoteSelect={handleNoteSelect}
              onNoteContextMenu={handleNoteContextMenu}
              notePreviews={allNotePreviews}
              onContextMenu={(event, id) => {
                event.preventDefault();
                event.stopPropagation();
                selectFeedGroup(id);
              }}
              indentationWidth={18}
              draggable={false}
            />
          ))}
          {earlierNodes.length > 0 && (
            <div className="feed-section-label feed-section-label-earlier">Earlier</div>
          )}
          {earlierNodes.map((node) => (
              <TreeNode
                key={node.id}
                node={node}
                depth={0}
                selectedIds={
                  activeFeedGroup ? new Set([activeFeedGroup]) : new Set()
                }
                selectedNoteIds={selectedNotes}
                showNotesAsChildren={shouldNestNotesInNavigation}
                edgeSnap={null}
                expanded={expanded}
                feedMode
                onSelect={(event, id) => {
                  event.stopPropagation();
                  selectFeedGroup(id);
                  if (feedNodeById.get(id)?.kind === "month") {
                    setExpanded((previous) => new Set(previous).add(id));
                  }
                }}
                onToggle={handleToggle}
                onNoteSelect={handleNoteSelect}
                onNoteContextMenu={handleNoteContextMenu}
                notePreviews={allNotePreviews}
                onContextMenu={(event, id) => {
                  event.preventDefault();
                  event.stopPropagation();
                  selectFeedGroup(id);
                }}
                indentationWidth={18}
                draggable={false}
              />
          ))}
          {earlierNodes.length === 0 && feedNoteFilter !== "all" && (
            <div className="feed-section-empty">No {feedNoteFilter} earlier notes.</div>
          )}
        </div>
      </div>
    </div>
  );
}
// Folder navigation shell — renders the real folder tree through the same
// TreeNode/TreeRow/NavNoteRow stack Feed uses, so both share one visual and
// component base (hover/selected state, fonts, indentation, drag-and-drop).
import type { MouseEvent as ReactMouseEvent } from "react";
import { useDroppable } from "@dnd-kit/core";
import type { TreeItem } from "../model/types";
import { TreeNode } from "./tree-node";
import type { NotePreview } from "@typenotes/shared/format";
import { ROOT_ID, dropId, type EdgeSnap } from "../model/tree-dnd";

const EMPTY_STRING_SET = new Set<string>();

type FoldersPanelProps = {
  treeData: TreeItem[];
  selectedIds: Set<string>;
  onSelect: (event: ReactMouseEvent, id: string) => void;
  edgeSnap: EdgeSnap;
  expanded: Set<string>;
  onToggle: (event: ReactMouseEvent, id: string) => void;
  onClearSelection: () => void;
  onPaneKeyDown?: (event: React.KeyboardEvent<HTMLDivElement>) => void;
  onPaneClick?: () => void;
  paneBodyRef?: React.Ref<HTMLDivElement>;
  renamingFolder: string | null;
  renameValue: string;
  setRenameValue: (value: string) => void;
  submitRenameFolder: () => void;
  cancelRenameFolder: () => void;
  onContextMenu: (event: ReactMouseEvent, id: string) => void;
  onEmptyAreaContextMenu?: (event: ReactMouseEvent) => void;
  showNotesAsChildren?: boolean;
  selectedNoteIds?: Set<string>;
  onNoteSelect?: (notePath: string, event: ReactMouseEvent, parentPath: string) => void;
  onNoteContextMenu?: (
    event: ReactMouseEvent,
    notePath: string,
    parentPath: string
  ) => void;
  notePreviews?: Record<string, NotePreview>;
  indentationWidth: number;
};

export function FoldersPanel({
  treeData,
  selectedIds,
  onSelect,
  edgeSnap,
  expanded,
  onToggle,
  onClearSelection,
  onPaneKeyDown,
  onPaneClick,
  paneBodyRef,
  renamingFolder,
  renameValue,
  setRenameValue,
  submitRenameFolder,
  cancelRenameFolder,
  onContextMenu,
  onEmptyAreaContextMenu,
  showNotesAsChildren = false,
  selectedNoteIds = EMPTY_STRING_SET,
  onNoteSelect,
  onNoteContextMenu,
  notePreviews = {},
  indentationWidth,
}: FoldersPanelProps) {
  const { setNodeRef: setRootDropRef, isOver } = useDroppable({
    id: dropId(ROOT_ID, "inside"),
  });
  const handleNoteSelect =
    onNoteSelect ??
    (() => {
      return;
    });
  const handleNoteContextMenu =
    onNoteContextMenu ??
    (() => {
      return;
    });

  return (
    <div className="pane-section sidebar-folders-section">
      <div className="nav-scroll-area">
        <div
          ref={(node) => {
            setRootDropRef(node);
            if (typeof paneBodyRef === "function") {
              paneBodyRef(node);
            } else if (paneBodyRef && "current" in paneBodyRef) {
              paneBodyRef.current = node;
            }
          }}
          className={`pane-body tree-root focus:outline-none${isOver ? " drop-inside" : ""}`}
          tabIndex={0}
          onKeyDownCapture={onPaneKeyDown}
          onClick={(event) => {
            if (onPaneClick) {
              onPaneClick();
            }
            if (event.target === event.currentTarget) {
              onClearSelection();
            }
          }}
          onContextMenu={(event) => {
            if (onEmptyAreaContextMenu && event.target === event.currentTarget) {
              onEmptyAreaContextMenu(event);
            }
          }}
        >
          {treeData.length === 0 ? <div className="empty">No folders yet.</div> : null}
          {treeData.map((node) => (
            <TreeNode
              key={node.id}
              node={node}
              depth={0}
              showNotesAsChildren={showNotesAsChildren}
              selectedNoteIds={selectedNoteIds}
              edgeSnap={edgeSnap}
              expanded={expanded}
              onToggle={onToggle}
              selectedIds={selectedIds}
              onSelect={onSelect}
              onNoteSelect={handleNoteSelect}
              onNoteContextMenu={handleNoteContextMenu}
              notePreviews={notePreviews}
              renamingFolder={renamingFolder}
              renameValue={renameValue}
              setRenameValue={setRenameValue}
              submitRenameFolder={submitRenameFolder}
              cancelRenameFolder={cancelRenameFolder}
              onContextMenu={onContextMenu}
              indentationWidth={indentationWidth}
            />
          ))}
        </div>
      </div>
    </div>
  );
}
// Shared navigation row chrome. Folder trees and feed buckets both use this
// surface; the parent decides which behaviors are enabled.
import type { MouseEvent as ReactMouseEvent } from "react";
import { useCallback } from "react";
import { useDraggable, useDroppable } from "@dnd-kit/core";
import { CSS } from "@dnd-kit/utilities";
import { CalendarDays } from "lucide-react";
import type { NavigationNode } from "../model/types";
import type { DragData } from "@typenotes/shared/types";
import { dropId } from "../model/tree-dnd";

export type TreeRowProps = {
  node: NavigationNode;
  depth: number;
  isSelected: boolean;
  hasNestedItems: boolean;
  edgePosition: "before" | "after" | null;
  isCollapsed: boolean;
  onSelect: (event: ReactMouseEvent, id: string) => void;
  onToggle: (event: ReactMouseEvent, id: string) => void;
  renaming?: boolean;
  renameValue?: string;
  setRenameValue?: (value: string) => void;
  submitRenameFolder?: () => void;
  cancelRenameFolder?: () => void;
  onContextMenu: (event: ReactMouseEvent, id: string) => void;
  indentationWidth: number;
  draggable?: boolean;
  feedMode?: boolean;
  renamingEnabled?: boolean;
};

export function TreeRow({
  node,
  depth,
  isSelected,
  hasNestedItems,
  edgePosition,
  isCollapsed,
  onSelect,
  onToggle,
  renaming = false,
  renameValue = "",
  setRenameValue = () => {
    return;
  },
  submitRenameFolder = () => {
    return;
  },
  cancelRenameFolder = () => {
    return;
  },
  onContextMenu,
  indentationWidth,
  draggable = true,
  feedMode = false,
  renamingEnabled = true,
}: TreeRowProps) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: node.id,
    data: { type: "folder", path: node.id } satisfies DragData,
    disabled: !draggable,
  });
  const { setNodeRef: setDropRef, isOver } = useDroppable({
    id: dropId(node.id, "inside"),
    data: { type: "folder", path: node.id } satisfies DragData,
    disabled: !draggable,
  });

  const setRefs = useCallback(
    (element: HTMLDivElement | null) => {
      setNodeRef(element);
      setDropRef(element);
    },
    [setNodeRef, setDropRef]
  );

  const style = {
    transform: isDragging ? undefined : CSS.Translate.toString(transform),
    paddingLeft: 12 + depth * indentationWidth,
  } as React.CSSProperties;
  const guideBaseLeft = 12 + indentationWidth / 2;

  return (
    <div
      ref={setRefs}
      style={style}
      className={`item-row folder-row${feedMode ? " feed-bucket-row" : ""}${
        isSelected ? " selected" : ""
      }${
        isDragging ? " is-dragging" : ""
      }${isOver && !edgePosition ? " drop-inside" : ""}${
        edgePosition === "before" ? " drop-before" : ""
      }${edgePosition === "after" ? " drop-after" : ""}`}
      data-folder={node.id}
      onClick={(event) => {
        const target = event.target as HTMLElement | null;
        if (target && target.closest(".tree-toggle, .rename-input")) {
          return;
        }
        onSelect(event, node.id);
      }}
      onContextMenu={(event) => {
        onContextMenu(event, node.id);
      }}
      {...listeners}
      {...attributes}
    >
      {depth > 0 && (
        <span className="tree-guides" aria-hidden>
          {Array.from({ length: depth }, (_, index) => (
            <span
              key={`depth-${index}`}
              className="tree-guide-vert"
              style={{ left: guideBaseLeft + index * indentationWidth }}
            />
          ))}
        </span>
      )}
      {hasNestedItems ? (
        <button
          type="button"
          className={`icon-btn tree-toggle${isCollapsed ? " is-collapsed" : ""}`}
          onClick={(event) => {
            event.stopPropagation();
            onToggle(event, node.id);
          }}
          onPointerDown={(event) => event.stopPropagation()}
          onMouseDown={(event) => event.stopPropagation()}
          aria-label={isCollapsed ? "Expand folder" : "Collapse folder"}
        >
          <svg viewBox="0 0 16 16" aria-hidden="true">
            <path d="M6 4l4 4-4 4" fill="none" stroke="currentColor" strokeWidth="1.6" />
          </svg>
        </button>
      ) : (
        <span className="icon-spacer" aria-hidden />
      )}
      {!renaming && (
        <span className="folder-glyph" aria-hidden>
          {feedMode ? (
            <CalendarDays size={15} />
          ) : hasNestedItems && !isCollapsed ? (
            <svg viewBox="0 0 24 24">
              <path
                d="M3 8a2.5 2.5 0 0 1 2.5-2.5h4L11.4 7h7.1A2.5 2.5 0 0 1 21 9.5V11"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              <path
                d="M2.8 10.5h18.4a1 1 0 0 1 .96 1.28l-1.65 5.5A2.5 2.5 0 0 1 18.1 19H5.9a2.5 2.5 0 0 1-2.4-1.72l-1.65-5.5a1 1 0 0 1 .95-1.28z"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinejoin="round"
              />
            </svg>
          ) : (
            <svg viewBox="0 0 24 24">
              <path
                d="M3 7.5A2.5 2.5 0 0 1 5.5 5H10l2 2h6.5A2.5 2.5 0 0 1 21 9.5v7A2.5 2.5 0 0 1 18.5 19h-13A2.5 2.5 0 0 1 3 16.5v-9z"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinejoin="round"
              />
            </svg>
          )}
        </span>
      )}
      {renaming && renamingEnabled ? (
        <input
          className="rename-input"
          value={renameValue}
          autoFocus
          onChange={(event) => setRenameValue(event.target.value)}
          onBlur={submitRenameFolder}
          onKeyDown={(event) => {
            event.stopPropagation();
            if (event.key === "Enter") {
              submitRenameFolder();
            }
            if (event.key === "Escape") {
              cancelRenameFolder();
            }
          }}
          onMouseDown={(event) => event.stopPropagation()}
          onClick={(event) => event.stopPropagation()}
        />
      ) : (
        <span className="item-label">
          {node.name}
          {feedMode && node.secondaryName ? (
            <span className="feed-secondary-label">{node.secondaryName}</span>
          ) : null}
        </span>
      )}
      {!renaming && node.noteCount ? (
        <span className="note-count" title={`${node.noteCount} notes`}>
          {node.noteCount}
        </span>
      ) : null}
    </div>
  );
}

