// Feed navigation renders synthetic time buckets, not the folder tree.
import type { MouseEvent as ReactMouseEvent, RefObject } from "react";
import { useCallback } from "react";
import { useShallow } from "zustand/react/shallow";

import { useEditor } from "@/features/notes/editor/hooks/editor-context";
import { useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
import { type DesktopContextMenuState } from "@/app/hooks/use-tree-interactions";
import { useSelection } from "@/app/state/selection-store";
import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
import { focusNoScroll } from "@/shared/lib/dom";
import { computeRangeSelection } from "@/shared/lib/selection";
import { isCurrentWeekFeedNode } from "../model/feed-tree-model";
import { TreeNode } from "./tree-node";

type FeedPanelProps = {
  paneBodyRef: RefObject<HTMLDivElement | null>;
  onNavigateToNotes?: () => void;
  onPaneClick?: () => void;
  onPaneKeyDown?: (event: React.KeyboardEvent<HTMLDivElement>) => void;
  onOpenContextMenu: (state: DesktopContextMenuState) => void;
};

export function FeedPanel({
  paneBodyRef,
  onNavigateToNotes,
  onPaneClick,
  onPaneKeyDown,
  onOpenContextMenu,
}: FeedPanelProps) {
  const { clearDraft, clearNote } = useEditor();
  const {
    feedTreeData,
    feedNodeById,
    feedNoteFilter,
    activeFeedGroup,
    setActiveFeedGroup,
    expanded,
    setExpanded,
    allNotePreviews,
    shouldNestNotesInNavigation,
  } = useNotesTree();
  const currentWeekNodes = feedTreeData.filter(isCurrentWeekFeedNode);
  const earlierNodes = feedTreeData.filter((node) => !isCurrentWeekFeedNode(node));
  const {
    selectFolder,
    selectNote,
    setSelectedFolders,
    setLastSelectedFolder,
    setActiveFolder,
    selectedNotes,
    setSelectedNotes,
    lastSelectedNote,
    setLastSelectedNote,
    setActiveNote,
  } = useSelection(
    useShallow((state) => ({
      selectFolder: state.selectFolder,
      selectNote: state.selectNote,
      setSelectedFolders: state.setSelectedFolders,
      setLastSelectedFolder: state.setLastSelectedFolder,
      setActiveFolder: state.setActiveFolder,
      selectedNotes: state.selectedNotes,
      setSelectedNotes: state.setSelectedNotes,
      lastSelectedNote: state.lastSelectedNote,
      setLastSelectedNote: state.setLastSelectedNote,
      setActiveNote: state.setActiveNote,
    }))
  );

  const selectFeedGroup = useCallback(
    (groupId: string) => {
      onNavigateToNotes?.();
      setActiveFeedGroup(groupId);
      selectFolder(FEED_FOLDER_PATH);
      clearDraft();
      clearNote();
      focusNoScroll(paneBodyRef.current);
    },
    [
      clearDraft,
      clearNote,
      onNavigateToNotes,
      paneBodyRef,
      selectFolder,
      setActiveFeedGroup,
    ]
  );

  const handleNoteSelect = useCallback(
    (notePath: string, event: ReactMouseEvent, parentPath: string) => {
      onNavigateToNotes?.();
      const parentNode = feedNodeById.get(parentPath);
      const notePaths = parentNode?.notes.map((note) => note.path) || [];
      selectNote(
        notePath,
        FEED_FOLDER_PATH,
        computeRangeSelection(event, selectedNotes, notePaths, lastSelectedNote, notePath)
      );
      setActiveFeedGroup(parentPath);
      if (shouldNestNotesInNavigation) {
        focusNoScroll(paneBodyRef.current);
      }
    },
    [
      feedNodeById,
      lastSelectedNote,
      onNavigateToNotes,
      paneBodyRef,
      selectNote,
      selectedNotes,
      setActiveFeedGroup,
      shouldNestNotesInNavigation,
    ]
  );

  const handleToggle = useCallback(
    (event: ReactMouseEvent, id: string) => {
      event.stopPropagation();
      setExpanded((prev) => {
        const next = new Set(prev);
        if (next.has(id)) {
          next.delete(id);
        } else {
          next.add(id);
        }
        return next;
      });
    },
    [setExpanded]
  );

  const handleNoteContextMenu = useCallback(
    (event: ReactMouseEvent, notePath: string, parentPath: string) => {
      event.preventDefault();
      event.stopPropagation();
      const parentNode = feedNodeById.get(parentPath);
      const notePaths = parentNode?.notes.map((note) => note.path) || [];
      const targetPaths =
        selectedNotes.size > 1 && selectedNotes.has(notePath) ? Array.from(selectedNotes) : [notePath];
      setSelectedFolders(new Set([FEED_FOLDER_PATH]));
      setLastSelectedFolder(FEED_FOLDER_PATH);
      setActiveFolder(FEED_FOLDER_PATH);
      if (!selectedNotes.has(notePath)) {
        setSelectedNotes(new Set([notePath]));
        setLastSelectedNote(notePath);
      }
      setActiveFeedGroup(parentPath);
      setActiveNote(notePath);
      focusNoScroll(paneBodyRef.current);
      onOpenContextMenu({
        kind: "note",
        x: event.clientX,
        y: event.clientY,
        path: notePath,
        parentPath,
        targetPaths: targetPaths.length > 0 ? targetPaths : notePaths,
      });
    },
    [
      feedNodeById,
      onOpenContextMenu,
      paneBodyRef,
      selectedNotes,
      setActiveFeedGroup,
      setActiveFolder,
      setActiveNote,
      setLastSelectedFolder,
      setLastSelectedNote,
      setSelectedFolders,
      setSelectedNotes,
    ]
  );

  return (
    <div className="feed-panel-layout">
      <div
        className="nav-scroll-area focus:outline-none"
        ref={paneBodyRef}
        tabIndex={0}
        onKeyDown={onPaneKeyDown}
        onClick={(event) => {
          if (onPaneClick) {
            onPaneClick();
          }
          if (event.target === event.currentTarget && feedTreeData[0]) {
            selectFeedGroup(activeFeedGroup || feedTreeData[0].id);
          }
        }}
      >
        <div className="pane-body tree-root feed-navigation-tree">
          <div className="feed-section-label">This week</div>
          {currentWeekNodes.map((node) => (
            <TreeNode
              key={node.id}
              node={node}
              depth={0}
              selectedIds={activeFeedGroup ? new Set([activeFeedGroup]) : new Set()}
              selectedNoteIds={selectedNotes}
              showNotesAsChildren={shouldNestNotesInNavigation}
              edgeSnap={null}
              expanded={expanded}
              feedMode
              onSelect={(event, id) => {
                event.stopPropagation();
                selectFeedGroup(id);
              }}
              onToggle={handleToggle}
              onNoteSelect={handleNoteSelect}
              onNoteContextMenu={handleNoteContextMenu}
              notePreviews={allNotePreviews}
              onContextMenu={(event, id) => {
                event.preventDefault();
                event.stopPropagation();
                selectFeedGroup(id);
              }}
              indentationWidth={18}
              draggable={false}
            />
          ))}
          {earlierNodes.length > 0 && (
            <div className="feed-section-label feed-section-label-earlier">Earlier</div>
          )}
          {earlierNodes.map((node) => (
              <TreeNode
                key={node.id}
                node={node}
                depth={0}
                selectedIds={
                  activeFeedGroup ? new Set([activeFeedGroup]) : new Set()
                }
                selectedNoteIds={selectedNotes}
                showNotesAsChildren={shouldNestNotesInNavigation}
                edgeSnap={null}
                expanded={expanded}
                feedMode
                onSelect={(event, id) => {
                  event.stopPropagation();
                  selectFeedGroup(id);
                  if (feedNodeById.get(id)?.kind === "month") {
                    setExpanded((previous) => new Set(previous).add(id));
                  }
                }}
                onToggle={handleToggle}
                onNoteSelect={handleNoteSelect}
                onNoteContextMenu={handleNoteContextMenu}
                notePreviews={allNotePreviews}
                onContextMenu={(event, id) => {
                  event.preventDefault();
                  event.stopPropagation();
                  selectFeedGroup(id);
                }}
                indentationWidth={18}
                draggable={false}
              />
          ))}
          {earlierNodes.length === 0 && feedNoteFilter !== "all" && (
            <div className="feed-section-empty">No {feedNoteFilter} earlier notes.</div>
          )}
        </div>
      </div>
    </div>
  );
}
